void _withTransform(
  Canvas canvas,
  double tx,
  double ty,
  double deg,
  void Function() draw,
) {
  canvas.save();
  canvas.translate(tx, ty);
  if (deg != 0) {
    canvas.rotate(deg * math.pi / 180.0);
  }
  draw();
  canvas.restore();
}

void _fillAndStroke(
  Canvas canvas,
  Path path,
  Color color,
  double strokeWidth,
) {
  final fillPaint = Paint()
    ..color = color
    ..style = PaintingStyle.fill;
  canvas.drawPath(path, fillPaint);
  if (strokeWidth > 0) {
    final strokePaint = Paint()
      ..color = color
      ..style = PaintingStyle.stroke
      ..strokeWidth = strokeWidth
      ..strokeJoin = StrokeJoin.round
      ..strokeCap = StrokeCap.round;
    canvas.drawPath(path, strokePaint);
  }
}

/// Paints the cleaned Full cut-out wordmark (ull.svg, tight viewBox 70 40 621 198).
class FullWordmarkPainter extends CustomPainter {
  const FullWordmarkPainter();

  static const double viewMinX = 70.0;
  static const double viewMinY = 40.0;
  static const double viewWidth = 621.0;
  static const double viewHeight = 198.0;
  static const double aspectRatio = viewHeight / viewWidth;

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    canvas.save();
    canvas.scale(size.width / viewWidth, size.height / viewHeight);
    canvas.translate(-viewMinX, -viewMinY);

    const shadowColor = Color(0x57111111);
    const white = Color(0xFFFFFFFF);
    final fillPaint = Paint()..style = PaintingStyle.fill;

    // 1. Letter 'o'
    _withTransform(canvas, 133.0, 152.0, -7.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathO, shadowColor, 19.0);
    });
    _withTransform(canvas, 127.5, 144.0, -7.0, () {
      canvas.drawOval(
        Rect.fromCenter(center: Offset.zero, width: 64.0, height: 70.0),
        fillPaint..color = white,
      );
      _fillAndStroke(canvas, _LogoVectorCache.pathO, white, 19.0);
      canvas.drawPath(
        _LogoVectorCache.pathO,
        fillPaint..color = const Color(0xFF10B981),
      );
    });

    // 2. Letter 'u'
    _withTransform(canvas, 228.0, 144.0, 5.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathU, shadowColor, 19.0);
    });
    _withTransform(canvas, 222.5, 136.0, 5.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathU, white, 19.0);
      canvas.drawPath(
        _LogoVectorCache.pathU,
        fillPaint..color = const Color(0xFFFF9F1C),
      );
    });

    // 3. Letter 'r'
    _withTransform(canvas, 323.0, 143.0, -4.0, () {
      canvas.drawPath(
        _LogoVectorCache.fullBoxROuter,
        fillPaint..color = shadowColor,
      );
    });
    _withTransform(canvas, 317.5, 135.0, -4.0, () {
      canvas.drawPath(_LogoVectorCache.fullBoxROuter, fillPaint..color = white);
      canvas.drawPath(
        _LogoVectorCache.fullBoxRInner,
        fillPaint..color = const Color(0xFFF3E3C3),
      );
    });
    _withTransform(canvas, 317.5, 136.5, -4.0, () {
      canvas.drawPath(
        _LogoVectorCache.pathR,
        fillPaint..color = const Color(0xFFC2452B),
      );
    });

    // 4. Letter 'n'
    _withTransform(canvas, 417.5, 143.0, 7.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathN, shadowColor, 19.0);
    });
    _withTransform(canvas, 412.0, 135.0, 7.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathN, white, 19.0);
      canvas.drawPath(
        _LogoVectorCache.pathN,
        fillPaint..color = const Color(0xFF2AA7E0),
      );
      fillPaint.color = const Color(0xFFFFD84D);
      canvas.drawCircle(const Offset(-28.0, -43.0), 5.5, fillPaint);
      canvas.drawCircle(const Offset(31.0, 38.0), 5.5, fillPaint);
    });

    // 5. Letter 'e'
    _withTransform(canvas, 515.5, 143.0, -3.0, () {
      canvas.drawPath(
        _LogoVectorCache.fullBoxEOuter,
        fillPaint..color = shadowColor,
      );
    });
    _withTransform(canvas, 510.0, 135.0, -3.0, () {
      canvas.drawPath(_LogoVectorCache.fullBoxEOuter, fillPaint..color = white);
      canvas.drawPath(
        _LogoVectorCache.fullBoxEInner,
        fillPaint..color = const Color(0xFF111111),
      );
    });
    _withTransform(canvas, 510.0, 146.5, -3.0, () {
      canvas.drawPath(
        _LogoVectorCache.pathE,
        fillPaint..color = const Color(0xFFFF4D6D),
      );
    });

    // 6. Letter 'y'
    _withTransform(canvas, 615.0, 165.0, 8.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathY, shadowColor, 19.0);
    });
    _withTransform(canvas, 609.5, 157.0, 8.0, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathY, white, 19.0);
      canvas.drawPath(
        _LogoVectorCache.pathY,
        fillPaint..color = const Color(0xFFA13CC9),
      );
    });

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant FullWordmarkPainter oldDelegate) => false;
}

/// Paints the owner-approved Compact A cut-out wordmark (compact-A.svg,
/// tight viewBox 40 30 616 166) with unified cream (#FFF8EE) sticker edge.
class CompactWordmarkPainter extends CustomPainter {
  const CompactWordmarkPainter();

  static const double viewMinX = 40.0;
  static const double viewMinY = 30.0;
  static const double viewWidth = 616.0;
  static const double viewHeight = 166.0;
  static const double aspectRatio = viewHeight / viewWidth;

  void _paintBackingShapes(Canvas canvas, Color color, double extraStroke) {
    final fillPaint = Paint()
      ..color = color
      ..style = PaintingStyle.fill;
    final sw = 28.0 + extraStroke;
    for (final cx in const [150.0, 242.5, 338.5, 435.5, 529.0]) {
      canvas.drawOval(
        Rect.fromCenter(
          center: Offset(cx, 103.0),
          width: 48.0 + extraStroke,
          height: 82.0 + extraStroke,
        ),
        fillPaint,
      );
    }
    _withTransform(canvas, 104.0, 105.0, -3.5, () {
      canvas.drawOval(
        Rect.fromCenter(center: Offset.zero, width: 64.0, height: 70.0),
        fillPaint,
      );
      _fillAndStroke(canvas, _LogoVectorCache.pathO, color, sw);
    });
    _withTransform(canvas, 196.0, 99.0, 2.2, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathU, color, sw);
    });
    _withTransform(canvas, 289.0, 101.0, -1.5, () {
      _fillAndStroke(canvas, _LogoVectorCache.compBoxROuter, color, extraStroke);
    });
    _withTransform(canvas, 388.0, 99.0, 2.5, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathN, color, sw);
    });
    _withTransform(canvas, 483.0, 101.0, -1.5, () {
      _fillAndStroke(canvas, _LogoVectorCache.compBoxEOuter, color, extraStroke);
    });
    _withTransform(canvas, 575.0, 116.0, 3.5, () {
      _fillAndStroke(canvas, _LogoVectorCache.pathY, color, sw);
    });
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    canvas.save();
    canvas.scale(size.width / viewWidth, size.height / viewHeight);
    canvas.translate(-viewMinX, -viewMinY);

    // 1. Unified shadow layer (shifted +3.5, +5)
    canvas.save();
    canvas.translate(3.5, 5.0);
    _paintBackingShapes(canvas, const Color(0x47161310), 0.0);
    canvas.restore();

    // 2. Thin ink sticker rim + unified cream (#FFF8EE) sticker backing
    _paintBackingShapes(canvas, const Color(0x581E1A15), 2.4);
    _paintBackingShapes(canvas, const Color(0xFFFFF8EE), 0.0);

    // 3. Foreground 6-colour letters
    final fillPaint = Paint()..style = PaintingStyle.fill;
    _withTransform(canvas, 104.0, 105.0, -3.5, () {
      canvas.drawPath(
        _LogoVectorCache.pathO,
        fillPaint..color = const Color(0xFF10B981),
      );
    });
    _withTransform(canvas, 196.0, 99.0, 2.2, () {
      canvas.drawPath(
        _LogoVectorCache.pathU,
        fillPaint..color = const Color(0xFFFF9F1C),
      );
    });
    _withTransform(canvas, 289.0, 101.0, -1.5, () {
      canvas.drawPath(
        _LogoVectorCache.compBoxRInner,
        fillPaint..color = const Color(0xFFF3E3C3),
      );
    });
    _withTransform(canvas, 289.0, 100.0, -1.5, () {
      canvas.drawPath(
        _LogoVectorCache.pathR,
        fillPaint..color = const Color(0xFFC2452B),
      );
    });
    _withTransform(canvas, 388.0, 99.0, 2.5, () {
      canvas.drawPath(
        _LogoVectorCache.pathN,
        fillPaint..color = const Color(0xFF2AA7E0),
      );
      fillPaint.color = const Color(0xFFFFD84D);
      canvas.drawCircle(const Offset(-28.0, -43.0), 5.5, fillPaint);
      canvas.drawCircle(const Offset(31.0, 38.0), 5.5, fillPaint);
    });
    _withTransform(canvas, 483.0, 101.0, -1.5, () {
      canvas.drawPath(
        _LogoVectorCache.compBoxEInner,
        fillPaint..color = const Color(0xFF111111),
      );
    });
    _withTransform(canvas, 483.0, 108.0, -1.5, () {
      canvas.drawPath(
        _LogoVectorCache.pathE,
        fillPaint..color = const Color(0xFFFF4D6D),
      );
    });
    _withTransform(canvas, 575.0, 116.0, 3.5, () {
      canvas.drawPath(
        _LogoVectorCache.pathY,
        fillPaint..color = const Color(0xFFA13CC9),
      );
    });

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant CompactWordmarkPainter oldDelegate) => false;
}

/// Paints the "o" sticker mark (tilted 'o' + underline bar) for <64px and square
/// slots, adapting cleanly to cream (light) and dark surfaces.
class OStickerPainter extends CustomPainter {
  const OStickerPainter({required this.isDark});

  final bool isDark;

  static const double viewMinX = 104.0;
  static const double viewMinY = 107.0;
  static const double viewSize = 224.0;

  @override
  void paint(Canvas canvas, Size size) {
    if (size.isEmpty) return;
    canvas.save();
    canvas.scale(size.width / viewSize, size.height / viewSize);
    canvas.translate(-viewMinX, -viewMinY);

    final shadow = isDark ? const Color(0xFF0C0B0A) : const Color(0xFF1A1A1A);
    final outline = isDark ? const Color(0xFFFFF8EE) : const Color(0xFF1A1A1A);
    final ringBody = isDark ? const Color(0xFFFF8A3D) : const Color(0xFFFFF8EE);
    const barBody = Color(0xFFFFD84D);

    final p = Paint()..style = PaintingStyle.fill;
    canvas.drawPath(_LogoVectorCache.oShadowRing, p..color = shadow);
    canvas.drawPath(_LogoVectorCache.oOutlineRing, p..color = outline);
    canvas.drawPath(_LogoVectorCache.oBodyRing, p..color = ringBody);
    canvas.drawPath(_LogoVectorCache.oShadowBar, p..color = shadow);
    canvas.drawPath(_LogoVectorCache.oOutlineBar, p..color = outline);
    canvas.drawPath(_LogoVectorCache.oBodyBar, p..color = barBody);

    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant OStickerPainter oldDelegate) =>
      oldDelegate.isDark != isDark;
}

/// Compact A cut-out wordmark (64–95px: Hub top bar, share cards 9:16 & 4:5,
/// Squad/travel posters, Wrapped summary).
class UiCompactWordmark extends StatelessWidget {
  const UiCompactWordmark({
    this.size = 84,
    this.semanticsLabel = 'Ourney',
    super.key,
  });

  /// Width of the compact wordmark in logical pixels.
  final double size;
  final String semanticsLabel;

  @override
  Widget build(BuildContext context) {
    final height = size * CompactWordmarkPainter.aspectRatio;
    return Semantics(
      container: true,
      label: semanticsLabel,
      image: true,
      excludeSemantics: true,
      child: MediaQuery.withNoTextScaling(
        child: SizedBox(
          width: size,
          height: height,
          child: const CustomPaint(painter: CompactWordmarkPainter()),
        ),
      ),
    );
  }
}

/// The "o" sticker mark (<64px or square icon slots: 16, 24, 48px on cream/dark).
class UiOSticker extends StatelessWidget {
  const UiOSticker({
    this.size = 24,
    this.isDark,
    this.semanticsLabel = 'Ourney',
    super.key,
  });

  /// Square dimension of the "o" sticker in logical pixels.
  final double size;

  /// Defaults to context.ui.isDark.
  final bool? isDark;
  final String semanticsLabel;

  @override
  Widget build(BuildContext context) {
    final dark = isDark ?? context.ui.isDark;
    return Semantics(
      container: true,
      label: semanticsLabel,
      image: true,
      excludeSemantics: true,
      child: MediaQuery.withNoTextScaling(
        child: SizedBox.square(
          dimension: size,
          child: CustomPaint(painter: OStickerPainter(isDark: dark)),
        ),
      ),
    );
  }
}
